                        .join(" · ")}
                    </span>
                    {state.status === "succeeded" && (
                      <Button
                        size="sm"
                        disabled={!!outputLoading}
                        onClick={() => inspect(state.blockId)}
                      >
                        {outputLoading === state.blockId ? "Loading…" : "Inspect output"}
