            {(["json", "xlsx", "csv"] as const).map((format) => (
              <Button
                key={format}
                size="sm"
                disabled={!!action}
                onClick={() => exportResearch(format)}
              >
                Export {format.toUpperCase()}
              </Button>
            ))}
          </div>
        </div>
      )}
    </section>
  );
}

